; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: test (Test harness (port I/O console)), starts in normal mode
; ============================================================

			org #4000

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			di
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; Main.bas 7: total = 0
			dw kw_l_mov, llit_0, var_total

			; Main.bas 8: name = "NTC"
			dw kw_strcpy, var_name, str0

			; Main.bas 22: For i = 0 To (MAX - 1)
			dw kw_ztov, var_i
for1_t:

			; Main.bas 24: squares(i) = square(i)
			dw p_square_c, var_i
			dw kw_aset, arr_squares, var_i, var_square_square

			; Main.bas 25: Next
			dw kw_next1l_n, var_i, 9, for1_t
for1_e:

			; Main.bas 26: i = 0
			dw kw_ztov, var_i

			; Main.bas 27: While (i < MAX)
			dw wh2_c_go
wh2_t:

			; Main.bas 29: If ((i Mod 2) = 0) Then
			dw kw_modvl, var_i, 2, tmp0
			dw kw_cpeqvl, tmp0, 0
			dw kw_goto_iffalse_n, if3_1

			; Main.bas 31: total = (total + squares(i))
			dw kw_aget, arr_squares, var_i, tmp1
			dw kw_l_itol, tmp1, ltmp1
			dw kw_l_add, var_total, ltmp1, var_total

			; Main.bas 32: End If
if3_1:

			; Main.bas 33: i = i + 1
			dw kw_inc, var_i

			; Main.bas 34: Wend
wh2_c:
			dw kw_scpltvl, var_i, 10
			dw kw_goto_iftrue_n, wh2_t
wh2_e:

			; Main.bas 35: Print ("Hello from " & (LCase$(name)))
			dw kw_strlcase, stmp0, var_name
			dw kw_printstrvar, str1
			dw kw_printstrvar, stmp0
			dw kw_printnl

			; Main.bas 36: Call report("even squares", total)
			dw kw_l_cstr, stmp1, var_total
			dw p_report_c, str2, stmp1

			; Main.bas 37: c.label = "count"
			dw kw_strcpy, var_counter_label, str3

			; Main.bas 38: For j = 10 To 1 Step -3
			dw kw_ltov, 10, var_j
for4_t:

			; Main.bas 40: Call c.add(j)
			dw p_counter_add_c, var_j

			; Main.bas 41: Print j; " ";
			dw kw_printint, var_j
			dw kw_printstrvar, str4

			; Main.bas 42: Next
			dw kw_nextdnl_n, var_j, -3, 1, for4_t
for4_e:

			; Main.bas 43: Print
			dw kw_printnl

			; Main.bas 44: Print c.describe(); " in "; c.steps; " steps"
			dw p_counter_describe_c
			dw kw_printstrvar, var_counter_describe_describe
			dw p_counter_steps_get_c
			dw kw_printstrvar, str5
			dw kw_printint, var_counter_steps_get_steps
			dw kw_printstrvar, str6
			dw kw_printnl
			dw kw_printnl0
			dw kw_printstrvar, str7
			dw kw_waitkey
			dw kw_stop

; ============================================================
; function square (normal mode)
; ============================================================

p_square:

			; Main.bas 14: square = (n * n)
			dw kw_mulvv, var_square_n, var_square_n, var_square_square
			dw p_square_r

; ============================================================
; sub report (normal mode)
; ============================================================

p_report:

			; Main.bas 19: Print ((label & ": ") & value)
			dw kw_printstrvar, var_report_label
			dw kw_printstrvar, str8
			dw kw_printstrvar, var_report_value
			dw kw_printnl
			dw p_report_r

; ============================================================
; sub add (normal mode)
; ============================================================

p_counter_add:

			; Counter.cls 10: Me.total = (Me.total + n)
			dw kw_l_itol, var_counter_add_n, ltmp1
			dw kw_l_add, var_counter_total, ltmp1, var_counter_total

			; Counter.cls 11: Call Me.p_bump()
			dw p_counter_p_bump_c
			dw p_counter_add_r

; ============================================================
; sub p_bump (normal mode)
; ============================================================

p_counter_p_bump:

			; Counter.cls 16: Me.p_steps = Me.p_steps + 1
			dw kw_inc, var_counter_p_steps
			dw p_counter_p_bump_r

; ============================================================
; propget steps (normal mode)
; ============================================================

p_counter_steps_get:

			; Counter.cls 21: steps = Me.p_steps
			dw kw_vtov, var_counter_p_steps, var_counter_steps_get_steps
			dw p_counter_steps_get_r

; ============================================================
; function describe (normal mode)
; ============================================================

p_counter_describe:

			; Counter.cls 26: describe = ((Me.label & "=") & Me.total)
			dw kw_strcpy, stmp0, var_counter_label
			dw kw_strcat, stmp0, str9
			dw kw_l_cstr, stmp1, var_counter_total
			dw kw_strcpy, var_counter_describe_describe, stmp0
			dw kw_strcat, var_counter_describe_describe, stmp1
			dw p_counter_describe_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

wh2_c_go:			ld sp, wh2_c
			jp ntc_xn

p_square_c:		; call square (normal)
			pop hl			; n
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_square_n), de
			ld hl, 0
			ld (var_square_square), hl
			ld (p_square_rs), sp
			ld sp, p_square
			jp ntc_xn
p_square_r:		; end of square
			ld sp, (p_square_rs)
			jp ntc_xn
p_report_c:		; call report (normal)
			pop hl			; label
			ld de, var_report_label
			ld b, 40
p_report_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_report_si0_e
			inc hl
			inc de
			djnz p_report_si0
			xor a
			ld (de), a
p_report_si0_e:
			pop hl			; value
			ld de, var_report_value
			ld b, 40
p_report_si1:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_report_si1_e
			inc hl
			inc de
			djnz p_report_si1
			xor a
			ld (de), a
p_report_si1_e:
			ld (p_report_rs), sp
			ld sp, p_report
			jp ntc_xn
p_report_r:		; end of report
			ld sp, (p_report_rs)
			jp ntc_xn
p_counter_add_c:		; call add (normal)
			pop hl			; n
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_counter_add_n), de
			ld (p_counter_add_rs), sp
			ld sp, p_counter_add
			jp ntc_xn
p_counter_add_r:		; end of add
			ld sp, (p_counter_add_rs)
			jp ntc_xn
p_counter_p_bump_c:		; call p_bump (normal)
			ld (p_counter_p_bump_rs), sp
			ld sp, p_counter_p_bump
			jp ntc_xn
p_counter_p_bump_r:		; end of p_bump
			ld sp, (p_counter_p_bump_rs)
			jp ntc_xn
p_counter_steps_get_c:		; call steps (normal)
			ld hl, 0
			ld (var_counter_steps_get_steps), hl
			ld (p_counter_steps_get_rs), sp
			ld sp, p_counter_steps_get
			jp ntc_xn
p_counter_steps_get_r:		; end of steps
			ld sp, (p_counter_steps_get_rs)
			jp ntc_xn
p_counter_describe_c:		; call describe (normal)
			xor a
			ld (var_counter_describe_describe), a
			ld (p_counter_describe_rs), sp
			ld sp, p_counter_describe
			jp ntc_xn
p_counter_describe_r:		; end of describe
			ld sp, (p_counter_describe_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_total:			dw 0, 0
			db 40			; capacity
var_name:			ds 41
var_i:			dw 0
var_square_square:			dw 0
			db 40			; capacity
var_counter_label:			ds 41
var_j:			dw 0
			db 40			; capacity
var_counter_describe_describe:			ds 41
var_counter_steps_get_steps:			dw 0
p_square_rs:			dw 0
var_square_n:			dw 0
p_report_rs:			dw 0
			db 40			; capacity
var_report_label:			ds 41
			db 40			; capacity
var_report_value:			ds 41
p_counter_add_rs:			dw 0
var_counter_add_n:			dw 0
var_counter_total:			dw 0, 0
p_counter_p_bump_rs:			dw 0
var_counter_p_steps:			dw 0
p_counter_steps_get_rs:			dw 0
p_counter_describe_rs:			dw 0
tmp0:			dw 0
tmp1:			dw 0
			db 40			; capacity
stmp0:			ds 41
			db 40			; capacity
stmp1:			ds 41
ltmp0:			dw 0, 0
ltmp1:			dw 0, 0

; numbers passed by address (read only)
llit_0:			dw 0, 0

; ============================================================
; Strings
; ============================================================

str0:			db "NTC", 0
str1:			db "Hello from ", 0
str2:			db "even squares", 0
str3:			db "count", 0
str4:			db " ", 0
str5:			db " in ", 0
str6:			db " steps", 0
str7:			db "Press a key", 0
str8:			db ": ", 0
str9:			db "=", 0

; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared
; ------------------------------------------------------------
; Scratch space
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread
ntc_ticks:		dw 0			; interrupt count (normal mode, platform handler)
ntc_gnlo:		db 0			; ntc_getn: low byte
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)
ntc_mode:		db 0			; div mode 0=quotient 1=remainder
ntc_sgnq:		db 0			; quotient sign (bit 7)
ntc_sgnr:		db 0			; remainder sign (bit 7)
ntc_lead:		db 0			; printint: digit seen
ntc_icnt:		db 0			; gets: chars typed
ntc_icap:		db 0			; gets: the buffer's capacity
ntc_sptr:		dw 0			; printbuf: text pointer
ntc_iptr:		dw 0			; gets: buffer pointer
ntc_ilink:		dw 0			; gets: where to go when done
ntc_ivar:		dw 0			; inputint / inkey: dest var
ntc_aptr:		dw 0			; atoi: text pointer
ntc_hookon:		db 0			; 1 = the Interrupt hook may run (set, and not running now)
ntc_hookset:	db 0			; 1 = an Interrupt hook is set
ntc_hookpend:	db 0			; 1 = an interrupt came, the hook runs at the next safe point
ntc_hook:		dw 0			; the hook Sub's call stub
ntc_hostix:		dw 0			; host platforms: IX kept over a firmware / BDOS call
ntc_rampt:		dw #7FC0		; the gate array's RAM setting now (B = port, C = value): the
								; Memory class keeps it, Graphics puts it back after drawing
ntc_numbuf:		ds 14			; printint / long print: digits (+ spaces for Option VBPrint)
				db 40			; ntc_inbuf's capacity (as every string variable has)
ntc_inbuf:		ds 41			; inputint: typed text

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			ld ix, ntc_next
			jp ntc_plat_getkey

;## ntc_xn ntc_data @shared
; normal mode "next": every normal mode keyword ends here (its ret
; became jp ntc_xn). Thread position to ntc_ip, real stack, one
; instruction with interrupts on, then back into the thread.
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			nop					; an interrupt can be taken here
			di
			ld sp, (ntc_ip)
			ret

;## kw_goto_iffalse (normal mode copy)
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse_n:
			pop hl
			jp z, ntc_xn
			ld sp, hl
			jp ntc_xn

;## kw_goto_iftrue (normal mode copy)
;kw_goto_iftrue, <label>  - branch if Z (true)
kw_goto_iftrue_n:
			pop hl
			jp nz, ntc_xn
			ld sp, hl
			jp ntc_xn

;## ntc_for_jump (normal mode copy)
; tails for the FOR / NEXT keywords. DE = var value, HL = limit,
; SP = thread at the label word. Signed compare by flipping bit 15.
; ntc_for_gt: jump to the label if var > limit, else skip it
ntc_for_gt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, carry = var > limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_lt: jump to the label if var < limit, else skip it
ntc_for_lt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, carry = var < limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_le: jump to the label if var <= limit (loop again). A not 0: the
; step took var past 32767 (or -32768): the loop ends (ntc_for_ge too)
ntc_for_le_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, no carry = var <= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_ge: jump to the label if var >= limit (loop again)
ntc_for_ge_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, no carry = var >= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
ntc_for_end_n:
			pop hl
			jp ntc_xn

;## kw_next1l (normal mode copy) ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit
kw_next1l_n:
			pop hl
			inc (hl)
			ld e, (hl)
			inc hl
			jr nz, ntc_n1l_nc_n
			inc (hl)
ntc_n1l_nc_n:
			ld d, (hl)
			pop hl
			ld a, d					; A = #FF when it went past 32767 (#8000)
			xor #80
			or e
			sub 1
			sbc a, a
			jp ntc_for_le_n

;## ntc_nextadd
; var += literal step. Pops var and step. Leaves DE = new value, A = #FF when
; it went past 32767 or -32768 (the loop ends), else 0.
ntc_nextadd:
			pop hl				; var
			pop bc				; step
			ld e, (hl)
			inc hl
			ld d, (hl)
			ex de, hl
			or a
			adc hl, bc			; P/V = past the end of the Integers
			ex de, hl			; DE = new value
			ld (hl), d
			dec hl
			ld (hl), e
			ld a, 0
			jp po, ntc_na_ok
			dec a
ntc_na_ok:
			jp (ix)

;## kw_nextdnl (normal mode copy) ntc_nextadd ntc_for_jump
;kw_nextdnl, <var>, <literal step>, <literal limit>, <toplabel>
;  NEXT for a negative STEP: add, back to the top while var >= limit
kw_nextdnl_n:
			ld ix, ntc_ndl_back_n
			jp ntc_nextadd
ntc_ndl_back_n:
			pop hl
			jp ntc_for_ge_n

;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			pop de
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			xor a
			pop hl
			ld (hl), a
			inc hl
			ld (hl), a
			ret

;## kw_inc
;kw_inc, <var>
kw_inc:
			pop hl
			inc (hl)
			ret nz
			inc hl
			inc (hl)
			ret

;## ntc_mul
; BC * DE -> pop destvar, store. Low 16 bits (same signed/unsigned)
ntc_mul:
			ld hl, 0
			ld a, 16
ntc_mul_loop:
			add hl, hl
			sla e
			rl d
			jr nc, ntc_mul_skip
			add hl, bc
ntc_mul_skip:
			dec a
			jr nz, ntc_mul_loop
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_mulvv ntc_mul
;kw_mulvv, <var1>, <var2>, <destvar>
kw_mulvv:
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			jp ntc_mul

;## ntc_div ntc_data
; HL / DE signed, truncating. (ntc_mode) 0 = quotient, 1 = remainder.
; Remainder takes the dividend's sign. Divide by zero gives
; quotient 0, remainder = dividend. Pops destvar and stores.
ntc_div:
			ld a, d
			or e
			jr nz, ntc_div_nz
			ld a, (ntc_mode)
			or a
			jr nz, ntc_div_store
			ld hl, 0
			jr ntc_div_store
ntc_div_nz:
			ld a, h
			ld (ntc_sgnr), a
			xor d
			ld (ntc_sgnq), a
			bit 7, h
			jr z, ntc_div_hpos
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_div_hpos:
			bit 7, d
			jr z, ntc_div_dpos
			xor a
			sub e
			ld e, a
			sbc a, a
			sub d
			ld d, a
ntc_div_dpos:
			ld a, h
			ld c, l
			ld hl, 0
			ld b, 16
ntc_div_loop:
			sla c
			rla
			adc hl, hl
			sbc hl, de
			jr nc, ntc_div_one
			add hl, de
			djnz ntc_div_loop
			jr ntc_div_done
ntc_div_one:
			inc c
			djnz ntc_div_loop
ntc_div_done:
			ld b, a
			ld a, (ntc_mode)
			or a
			jr z, ntc_div_q
			ld a, (ntc_sgnr)
			jr ntc_div_sign
ntc_div_q:
			ld h, b
			ld l, c
			ld a, (ntc_sgnq)
ntc_div_sign:
			rla
			jr nc, ntc_div_store
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_div_store:
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_divvl ntc_div
;kw_divvl, <var>, <literal>, <destvar>
kw_divvl:
			xor a
			ld (ntc_mode), a
ntc_divvl:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			pop de
			jp ntc_div

;## kw_modvl kw_divvl
;kw_modvl, <var>, <literal>, <destvar>
kw_modvl:
			ld a, 1
			ld (ntc_mode), a
			jp ntc_divvl

;## ntc_cmp
ntc_cmp_slt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ult:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sge:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_uge:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_sgt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ugt:
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sle:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ule:
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_eq:
			or a
			sbc hl, de
			ret
ntc_cmp_ne:
			or a
			sbc hl, de
			jr z, ntc_cmp_ne_f
			xor a
			ret
ntc_cmp_ne_f:
			or 1
			ret

;## kw_scpltvl ntc_cmp
;kw_scpltvl, <var>, <literal>
kw_scpltvl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_slt

;## kw_cpeqvl ntc_cmp
kw_cpeqvl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_eq

;## kw_aget
;kw_aget, <arraybase>, <indexvar>, <destvar>
kw_aget:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, de
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_aset
;kw_aset, <arraybase>, <indexvar>, <sourcevar>
kw_aset:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, de
			ex de, hl
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			ex de, hl
			ld (hl), c
			inc hl
			ld (hl), b
			ret

;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			pop de
			pop hl
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcpy_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcpy_loop
			xor a
			ld (de), a
			ret

;## kw_strcat
;kw_strcat, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcat:
			pop de
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcat_end:
			ld a, (de)
			or a
			jr z, ntc_strcat_copy
			inc de
			djnz ntc_strcat_end
			pop hl
			ret
ntc_strcat_copy:
			pop hl
ntc_strcat_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcat_loop
			xor a
			ld (de), a
			ret

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			ld a, (ntc_curx)
			or a
			ret z
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_strlcase
;kw_strlcase, <dest>, <src>  - LCase$
kw_strlcase:
			pop de
			pop hl
ntc_lc_loop:
			ld a, (hl)
			cp 'A'
			jr c, ntc_lc_put
			cp 'Z' + 1
			jr nc, ntc_lc_put
			add a, 32
ntc_lc_put:
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			jr ntc_lc_loop

;## ntc_ldata
ntc_la:			ds 4
ntc_lb:			ds 4
ntc_lr:			ds 4
ntc_lt:			ds 4
ntc_lsgn:		db 0
ntc_lcnt:		db 0
ntc_ldst:		dw 0
ntc_lix:		dw 0

;## kw_l_mov
;kw_l_mov, <src>, <dest>  - dest = src (4 bytes)
kw_l_mov:
			pop hl
			pop de
			ldi
			ldi
			ldi
			ldi
			ret

;## kw_l_itol
;kw_l_itol, <intvar>, <dest>  - Integer to Long (sign extended)
kw_l_itol:
			pop hl
			pop de
			ld a, (hl)
			ld (de), a
			inc hl
			inc de
			ld a, (hl)
			ld (de), a
			inc de
			rla
			sbc a, a
			ld (de), a
			inc de
			ld (de), a
			ret

;## kw_l_add
;kw_l_add, <a>, <b>, <dest>  - a + b
kw_l_add:
			pop hl
			pop de
			pop ix
			ld a, (de)
			add a, (hl)
			ld (ix+0), a
			inc hl
			inc de
			ld a, (de)
			adc a, (hl)
			ld (ix+1), a
			inc hl
			inc de
			ld a, (de)
			adc a, (hl)
			ld (ix+2), a
			inc hl
			inc de
			ld a, (de)
			adc a, (hl)
			ld (ix+3), a
			ret

;## ntc_ltoa ntc_ldata ntc_data
; Long at (HL) to text at DE, 0 at the end. jp (ix) back. Uses IY.
ntc_ltoa:
			ld (ntc_ldst), de
			ld de, ntc_la
			ldi
			ldi
			ldi
			ldi
			ld de, (ntc_ldst)
			ld a, (ntc_la+3)
			or a
			jp p, ntc_lta_pos
			ld a, '-'
			ld (de), a
			inc de
			ld hl, ntc_la
			xor a
			sub (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
ntc_lta_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_lpow10
ntc_lta_pow:
			ld a, (iy+0)
			or (iy+1)
			or (iy+2)
			or (iy+3)
			jr z, ntc_lta_last
			ld c, '0'
ntc_lta_sub:
			ld hl, ntc_la
			ld a, (hl)
			sub (iy+0)
			ld (ntc_lt), a
			inc hl
			ld a, (hl)
			sbc a, (iy+1)
			ld (ntc_lt+1), a
			inc hl
			ld a, (hl)
			sbc a, (iy+2)
			ld (ntc_lt+2), a
			inc hl
			ld a, (hl)
			sbc a, (iy+3)
			ld (ntc_lt+3), a
			jr c, ntc_lta_dig
			ld hl, (ntc_lt)
			ld (ntc_la), hl
			ld hl, (ntc_lt+2)
			ld (ntc_la+2), hl
			inc c
			jr ntc_lta_sub
ntc_lta_dig:
			ld a, c
			cp '0'
			jr nz, ntc_lta_out
			ld a, (ntc_lead)
			or a
			jr z, ntc_lta_skip
			ld a, c
ntc_lta_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_lta_skip:
			ld bc, 4
			add iy, bc
			jr ntc_lta_pow
ntc_lta_last:
			ld a, (ntc_la)
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_lpow10:		dd 1000000000, 100000000, 10000000, 1000000, 100000, 10000, 1000, 100, 10, 0

;## kw_l_cstr ntc_ltoa
;kw_l_cstr, <dest>, <long>  - Long to text
kw_l_cstr:
			pop de
			pop hl
			ld ix, ntc_next
			jp ntc_ltoa

;## kw_bssinit ntc_data ntc_plat_memtop ntc_plat_screen kw_stop @shared
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  it (from ntc_end, not in its file). Check they fit under the platform's top (and 256 bytes
;  under the real stack when that is above them), then clear them. Too big: a message, the
;  program stops.
kw_bssinit:
			pop hl
			ld (ntc_bsa), hl
			pop bc
			ld (ntc_bsz), bc
			ld (ntc_bsp), sp
			ld sp, (ntc_csp)
			add hl, bc				; HL = their end
			ex de, hl
			call ntc_plat_memtop	; HL = the platform's top
			or a
			sbc hl, de
			jr c, ntc_bs_big
			ld hl, (ntc_csp)		; the real stack, when above them
			ld bc, (ntc_bsa)
			or a
			sbc hl, bc
			jr c, ntc_bs_ok
			ld hl, (ntc_csp)
			ld bc, -256
			add hl, bc
			or a
			sbc hl, de
			jr c, ntc_bs_big
ntc_bs_ok:
			ld bc, (ntc_bsz)
			ld a, b
			or c
			jr z, ntc_bs_done
			ld hl, (ntc_bsa)
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_bs_done
			ld d, h
			ld e, l
			inc de
			ldir
ntc_bs_done:
			ld sp, (ntc_bsp)
			ret
ntc_bs_big:
			ld hl, ntc_bstxt
ntc_bs_pl:
			ld a, (hl)
			or a
			jr z, ntc_bs_stop
			inc hl
			ld (ntc_bsa), hl
			ld ix, ntc_bs_pn
			jp ntc_plat_putc
ntc_bs_pn:
			ld hl, (ntc_bsa)
			jr ntc_bs_pl
ntc_bs_stop:
			ld ix, kw_stop
			jp ntc_plat_newline
ntc_bsa:		dw 0
ntc_bsz:		dw 0
ntc_bsp:		dw 0
ntc_bstxt:		db "Not enough memory for the arrays", 0

;## ntc_plat_data
ntc_curx:		db 0			; cursor column (0 based)
ntc_cury:		db 0			; cursor row (0 based)
ntc_scols:		db 40			; columns in this mode
ntc_srows:		db 25			; rows
ntc_wrapped:	db 0			; 1 = the last character wrapped to the next line

;## ntc_plat_screen ntc_plat_data ntc_data
; ntc_plat_putc - A = character: out, move on, new line after the last column
ntc_plat_putc:
			out (#fe), a
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			ld (ntc_curx), a
			cp b
			jr z, ntc_pc_wrap
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_pc_wrap:
			ld a, 1				; wrapped: a new line straight after does nothing
			ld (ntc_wrapped), a
			jr ntc_nl_do

; ntc_plat_newline - column 0, next row (the harness scrolls); nothing straight after a wrap
ntc_plat_newline:
			ld a, (ntc_wrapped)
			or a
			jr z, ntc_nl_do
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_nl_do:
			out (#f9), a
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp 25
			jr c, ntc_nl_row
			ld a, 24
ntc_nl_row:
			ld (ntc_cury), a
			jp (ix)

; ntc_plat_backspace - back one and blank that cell
ntc_plat_backspace:
			xor a
			ld (ntc_wrapped), a
			ld a, (ntc_curx)
			or a
			jr nz, ntc_bs_col
			ld a, (ntc_cury)
			or a
			jr z, ntc_bs_none
			dec a
			ld (ntc_cury), a
			ld a, (ntc_scols)
ntc_bs_col:
			dec a
			ld (ntc_curx), a
			out (#f5), a
ntc_bs_none:
			jp (ix)

; ntc_plat_cls - clear, cursor home
ntc_plat_cls:
			out (#fc), a
			xor a
			ld (ntc_wrapped), a
			ld (ntc_curx), a
			ld (ntc_cury), a
			jp (ix)

; ntc_plat_mode - A = mode 0-2 (3 = 2): columns, clear
ntc_plat_mode:
			cp 3
			jr c, ntc_md_ok
			ld a, 2
ntc_md_ok:
			out (#fa), a
			ld b, 20
			or a
			jr z, ntc_md_set
			ld b, 40
			dec a
			jr z, ntc_md_set
			ld b, 80
ntc_md_set:
			ld a, b
			ld (ntc_scols), a
			jr ntc_plat_cls

; ntc_plat_locate - H = column, L = row, 1 based, kept on screen
ntc_plat_locate:
			xor a
			ld (ntc_wrapped), a
			ld a, h
			or a
			jr z, ntc_lc_x0
			dec a
ntc_lc_x0:
			ld c, a
			ld a, (ntc_scols)
			dec a
			cp c
			jr c, ntc_lc_xmax
			ld a, c
ntc_lc_xmax:
			ld (ntc_curx), a
			ld a, l
			or a
			jr z, ntc_lc_y0
			dec a
ntc_lc_y0:
			cp 25
			jr c, ntc_lc_ymax
			ld a, 24
ntc_lc_ymax:
			ld (ntc_cury), a
			ld a, (ntc_curx)
			inc a
			out (#fb), a
			ld a, (ntc_cury)
			inc a
			out (#fb), a
			jp (ix)

;## ntc_plat_key ntc_data
; ntc_plat_scankey - A = key pressed or 0
ntc_plat_scankey:
			in a, (#f8)
			jp (ix)

; ntc_plat_getkey - wait for a key, A = key
ntc_plat_getkey:
			in a, (#fd)
			jp (ix)

;## ntc_plat_exit ntc_plat_data
ntc_plat_exit:
			jp (ix)

;## ntc_plat_memtop
; ntc_plat_memtop - HL = the first byte the Memory class's Small heap must not
; use (the harness's stack, below it, comes off too). Called on the real
; stack (call / ret), only by the Memory class.
ntc_plat_memtop:
			ld hl, #C000
			ret


ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_squares		equ ntc_bss + 0		; 20 bytes
ntc_bss_size	equ 20
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
